insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (1, 'H.C. Andersen', '2. april 1805', '4. august 1875', '1805-04-02', '1875-08-04', 1805, 1875, 'Odense', 'København', 'Forfatter', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 97, 'Verdens mest elskede eventyrdigter. Hans eventyr som ''Den grimme ælling'', ''Den lille havfrue'' og ''Kejserens nye klæder'' er oversat til over 125 sprog.', 'Hans Christian Andersen blev født i Odense i fattige kår og rejste som 14-årig til København for at søge lykken. Efter år med modgang brød han igennem som forfatter og blev en af verdenshistoriens mest oversatte forfattere. Hans eventyr kombinerede folkelig fortælletradition med dyb menneskelig indsigt og blev elsket af både børn og voksne verden over.', 'Guldalderen', '1800-tallet', 'Danmark i Guldalderen', 'writers', 'https://da.wikipedia.org/wiki/H.C._Andersen', true)
