insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (2, 'Søren Kierkegaard', '5. maj 1813', '11. november 1855', '1813-05-05', '1855-11-11', 1813, 1855, 'København', 'København', 'Filosof og teolog', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 94, 'Eksistentialismens fader. Hans filosofi om angst, fortvivlelse og troens spring har formet moderne tænkning dybt.', 'Søren Aabye Kierkegaard var en dansk filosof, teolog og forfatter, der regnes som eksistentialismens grundlægger. Han udfordrede den etablerede kirke og Hegels filosofi med sine skrifter om den enkeltes ansvar og eksistens. Hans værker som ''Enten – Eller'' og ''Begrebet Angest'' er grundtekster i vestlig filosofi.', 'Guldalderen', '1800-tallet', 'Danmark i Guldalderen', 'thinkers', 'https://da.wikipedia.org/wiki/S%C3%B8ren_Kierkegaard', true)
