insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (3, 'Niels Bohr', '7. oktober 1885', '18. november 1962', '1885-10-07', '1962-11-18', 1885, 1962, 'København', 'København', 'Fysiker', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 96, 'Nobelpristager i fysik og en af grundlæggerne af atomfysikken. Hans atommodel fra 1913 ændrede vores forståelse af stoffets opbygning.', 'Niels Henrik David Bohr modtog Nobelprisen i fysik i 1922 for sin forskning i atomets struktur. Hans institut ved Københavns Universitet blev et internationalt centrum for kvantefysikken. Under besættelsen flygtede han i 1943 til Sverige og videre til England og USA. Efter krigen arbejdede han for fredelig brug af atomenergi.', 'Verdenskrigenes tid', '1900-tallet', 'Danmark i Verdenskrigenes tid', 'science', 'https://da.wikipedia.org/wiki/Niels_Bohr', true)
