insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (4, 'Niels Juel', '8. maj 1629', '8. april 1697', '1629-05-08', '1697-04-08', 1629, 1697, 'Christiania (Oslo)', 'København', 'Admiral', 'Holmens Kirke', 2, 'København', 55.6764, 12.5813, 'cemetery', 91, 'En af Danmarks største søhelte. Hans sejr i Slaget i Køge Bugt i 1677 er den danske flådes mest berømte.', 'Niels Juel var en dansk-norsk admiral, der ledte den danske flåde under Skånske Krig. Hans taktiske evner i Slaget ved Femern og Slaget i Køge Bugt i 1677 sikrede dansk kontrol over Østersøen og gjorde ham til en af Danmarks mest fejrede søhelte. Han er begravet i Holmens Kirke.', 'Enevælden', '1600-tallet', 'Danmark i Enevælden', 'naval', 'https://da.wikipedia.org/wiki/Niels_Juel', true)
