insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (5, 'H.C. Ørsted', '14. august 1777', '9. marts 1851', '1777-08-14', '1851-03-09', 1777, 1851, 'Rudkøbing', 'København', 'Fysiker og kemiker', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 90, 'Opdagede elektromagnetismen i 1820 — sammenhængen mellem elektricitet og magnetisme, som al moderne elektroteknik bygger på.', 'Hans Christian Ørsted voksede op som apotekersøn i Rudkøbing på Langeland. I 1820 viste han, at en elektrisk strøm påvirker en kompasnål, og opdagelsen gjorde ham berømt i hele Europa. Han grundlagde Polyteknisk Læreanstalt (i dag DTU) i 1829 og arbejdede for at udbrede naturvidenskaben til hele befolkningen.', 'Guldalderen', '1800-tallet', 'Danmark i Guldalderen', 'science', 'https://da.wikipedia.org/wiki/H.C._%C3%98rsted', true)
