insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (6, 'Martin Andersen Nexø', '26. juni 1869', '1. juni 1954', '1869-06-26', '1954-06-01', 1869, 1954, 'København (Christianshavn)', 'Dresden', 'Forfatter', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 90, 'Arbejderklassens store fortæller. ''Pelle Erobreren'' og ''Ditte Menneskebarn'' skildrer fattigdom og kamp for et bedre liv.', 'Martin Andersen Nexø voksede op i fattigdom i København og på Bornholm, hvor han tog navn efter byen Nexø. Hans romaner ''Pelle Erobreren'' og ''Ditte Menneskebarn'' gav stemme til landarbejdere, tjenestepiger og industriarbejdere og blev læst i hele verden. Han døde i Dresden i 1954 og blev begravet på Assistens Kirkegård.', 'Det moderne gennembrud', '1900-tallet', 'Danmark i det moderne gennembrud', 'writers', 'https://da.wikipedia.org/wiki/Martin_Andersen_Nex%C3%B8', true)
