insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (7, 'Dan Turèll', '19. februar 1946', '15. oktober 1993', '1946-02-19', '1993-10-15', 1946, 1993, 'Vangede', 'København', 'Forfatter og digter', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 90, '''Onkel Danny'' — digter, krimiforfatter og København-skildrer med sort neglelak og en uendelig kærlighed til hverdagen.', 'Dan Turèll skrev digte, essays, erindringer og krimier og blev en af sin generations mest folkekære forfattere. ''Vangede Billeder'' fra 1975 er en klassiker om opvækst i forstaden, og hans ''Mord''-serie gjorde Vesterbro til krimiscene. Han døde af kræft i 1993.', 'Velfærdssamfundet', '1900-tallet', 'Danmark i Velfærdssamfundet', 'writers', 'https://da.wikipedia.org/wiki/Dan_Tur%C3%A8ll', true)
