insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (8, 'Tove Ditlevsen', '14. december 1917', '7. marts 1976', '1917-12-14', '1976-03-07', 1917, 1976, 'København (Vesterbro)', 'København', 'Forfatter og digter', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 90, 'Digteren fra Vesterbro, hvis erindringer om barndom, ungdom og afhængighed i dag læses verden over.', 'Tove Ditlevsen voksede op i en arbejderfamilie på Vesterbro og debuterede med digtsamlingen ''Pigesind'' i 1939. Hendes erindringsværker ''Barndom'', ''Ungdom'' og ''Gift'' — i dag kendt som Københavnertrilogien — skildrer ærligt kvindeliv, fattigdom og misbrug og er oversat til mange sprog.', 'Velfærdssamfundet', '1900-tallet', 'Danmark i Velfærdssamfundet', 'writers', 'https://da.wikipedia.org/wiki/Tove_Ditlevsen', true)
