insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (9, 'Christen Købke', '26. maj 1810', '7. februar 1848', '1810-05-26', '1848-02-07', 1810, 1848, 'København', 'København', 'Maler', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 90, 'Guldaldermaler, der fangede det stille, klare lys over København og Frederiksborg Slot.', 'Christen Købke var elev af C.W. Eckersberg på Kunstakademiet og blev en af guldalderens fineste malere. Hans billeder som ''Frederiksborg Slot ved aftenbelysning'' og ''Udsigt fra Dosseringen'' viser hverdagens København i et roligt, præcist lys. Han døde kun 37 år gammel.', 'Guldalderen', '1800-tallet', 'Danmark i Guldalderen', 'art', 'https://da.wikipedia.org/wiki/Christen_K%C3%B8bke', true)
