insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (10, 'C.W. Eckersberg', '2. januar 1783', '22. juli 1853', '1783-01-02', '1853-07-22', 1783, 1853, 'Blåkrog ved Aabenraa', 'København', 'Maler', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 90, 'Kaldt ''den danske malerkunsts fader''. Som professor lærte han en hel generation af guldaldermalere at se efter naturen.', 'Christoffer Wilhelm Eckersberg studerede i Paris hos Jacques-Louis David og derefter i Rom. Som professor ved Kunstakademiet fra 1818 lærte han eleverne at male direkte efter naturen, og blandt dem var Købke, Marstrand og Rørbye. Han døde af kolera under epidemien i 1853.', 'Guldalderen', '1800-tallet', 'Danmark i Guldalderen', 'art', 'https://da.wikipedia.org/wiki/C.W._Eckersberg', true)
