insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (11, 'Rasmus Rask', '22. november 1787', '14. november 1832', '1787-11-22', '1832-11-14', 1787, 1832, 'Brændekilde på Fyn', 'København', 'Sprogforsker', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 90, 'Sprogforskeren, der var med til at vise, at de europæiske og indiske sprog er i familie med hinanden.', 'Rasmus Rask var bondesøn fra Fyn og en af grundlæggerne af den sammenlignende sprogvidenskab. Han lærte sig et væld af sprog og rejste fra 1816 til 1823 gennem Rusland og Persien til Indien og Ceylon for at studere dem. Hans arbejde med islandsk og de nordiske sprog er stadig grundlæggende.', 'Guldalderen', '1800-tallet', 'Danmark i Guldalderen', 'science', 'https://da.wikipedia.org/wiki/Rasmus_Rask', true)
