insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (13, 'Ben Webster', '27. marts 1909', '20. september 1973', '1909-03-27', '1973-09-20', 1909, 1973, 'Kansas City, USA', 'Amsterdam', 'Jazzsaxofonist', 'Assistens Kirkegård', 1, 'København', 55.6905, 12.5494, 'cemetery', 90, 'Amerikansk tenorsaxofonist fra Duke Ellingtons orkester, som fandt sit andet hjem i København.', 'Ben Webster var en af jazzens store tenorsaxofonister og spillede i Duke Ellingtons orkester i begyndelsen af 1940''erne. I 1960''erne slog han sig ned i København, hvor han spillede med danske musikere på bl.a. Jazzhus Montmartre. Han døde i Amsterdam efter en koncert og blev begravet på Assistens Kirkegård.', 'Verdenskrigenes tid', '1900-tallet', 'Danmark i Verdenskrigenes tid', 'music', 'https://da.wikipedia.org/wiki/Ben_Webster', true)
