insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (14, 'Peter Wessel Tordenskiold', '28. oktober 1690', '20. november 1720', '1690-10-28', '1720-11-20', 1690, 1720, 'Trondheim', 'Ved Hannover', 'Viceadmiral', 'Holmens Kirke', 2, 'København', 55.6764, 12.5813, 'cemetery', 90, 'Den dristige søhelt fra Store Nordiske Krig, der vandt Slaget i Dynekilen og døde i en duel kun 30 år gammel.', 'Peter Wessel blev født i Trondheim og gjorde lynkarriere i den dansk-norske flåde under Store Nordiske Krig. I 1716 blev han adlet med navnet Tordenskiold, og samme år ødelagde han en svensk forsyningsflåde i Dynekilen. Han blev dræbt i en duel i Tyskland i 1720 og ligger i Holmens Kirke.', 'Enevælden', '1700-tallet', 'Danmark i Enevælden', 'naval', 'https://da.wikipedia.org/wiki/Peter_Wessel_Tordenskiold', true)
