insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (15, 'Carl Nielsen', '9. juni 1865', '3. oktober 1931', '1865-06-09', '1931-10-03', 1865, 1931, 'Sortelung ved Nørre Lyndelse', 'København', 'Komponist', 'Vestre Kirkegård', 3, 'København', 55.647, 12.529, 'cemetery', 90, 'Danmarks største komponist. Symfonier, operaen ''Maskarade'' og sange, som hele landet stadig synger.', 'Carl Nielsen voksede op i fattige kår på Fyn og spillede som dreng i et militærorkester i Odense. Han blev Danmarks førende komponist med seks symfonier, operaen ''Maskarade'' og et stort antal folkelige sange. Han var gift med billedhuggeren Anne Marie Carl-Nielsen.', 'Det moderne gennembrud', '1800-tallet', 'Danmark i det moderne gennembrud', 'music', 'https://da.wikipedia.org/wiki/Carl_Nielsen', true)
