insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (16, 'Adam Oehlenschläger', '14. november 1779', '20. januar 1850', '1779-11-14', '1850-01-20', 1779, 1850, 'Vesterbro, København', 'København', 'Digter', 'Frederiksberg Ældre Kirkegård', 4, 'Frederiksberg', 55.673, 12.5285, 'cemetery', 90, 'Romantikkens banebryder og forfatter til ''Der er et yndigt land''. Hyldet som ''Nordens digterkonge''.', 'Adam Oehlenschläger indledte den danske romantik med digtet ''Guldhornene'' i 1802. Han skrev tragedier om nordisk oldtid og i 1819 teksten til ''Der er et yndigt land'', der i dag er Danmarks nationalsang. I 1829 blev han kronet med laurbær som Nordens digterkonge i Lund.', 'Guldalderen', '1800-tallet', 'Danmark i Guldalderen', 'writers', 'https://da.wikipedia.org/wiki/Adam_Oehlenschl%C3%A4ger', true)
