insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (17, 'Bertel Thorvaldsen', '19. november 1770', '24. marts 1844', '1770-11-19', '1844-03-24', 1770, 1844, 'København', 'København', 'Billedhugger', 'Thorvaldsens Museum', 5, 'København', 55.677, 12.5777, 'cemetery', 90, 'Europas mest berømte billedhugger i sin tid. Han ligger begravet i gården i sit eget museum.', 'Bertel Thorvaldsen rejste i 1797 til Rom, hvor han boede i over 40 år og blev en af nyklassicismens største billedhuggere. Gennembruddet kom med statuen ''Jason med det gyldne skind''. Han vendte hjem i 1838 til en heltemodtagelse, og Thorvaldsens Museum åbnede i 1848 med hans grav i gården.', 'Guldalderen', '1800-tallet', 'Danmark i Guldalderen', 'art', 'https://da.wikipedia.org/wiki/Bertel_Thorvaldsen', true)
