insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (18, 'Margrete 1.', 'marts 1353', '28. oktober 1412', null, '1412-10-28', 1353, 1412, 'Søborg Slot', 'Flensborg Fjord', 'Dronning og rigsforstander', 'Roskilde Domkirke', 6, 'Roskilde', 55.6426, 12.0803, 'cemetery', 90, 'Nordens mægtigste dronning, der samlede Danmark, Norge og Sverige i Kalmarunionen i 1397.', 'Margrete var datter af Valdemar Atterdag. Efter sin søn Olufs død i 1387 blev hun enerådende over Danmark og kort efter også Norge og Sverige. Ved Kalmarunionen i 1397 blev hendes grandnevø Erik af Pommern kronet som konge af alle tre riger, mens Margrete i praksis regerede til sin død i 1412.', 'Middelalderen', '1300-tallet', 'Danmark i Middelalderen', 'royals', 'https://da.wikipedia.org/wiki/Margrete_1.', true)
