insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (19, 'Christian 4.', '12. april 1577', '28. februar 1648', '1577-04-12', '1648-02-28', 1577, 1648, 'Frederiksborg Slot', 'Rosenborg Slot', 'Konge', 'Roskilde Domkirke', 6, 'Roskilde', 55.6426, 12.0803, 'cemetery', 90, 'Byggekongen bag Rundetårn, Børsen og Rosenborg — og Danmarks længst regerende konge i 60 år.', 'Christian 4. blev konge som 11-årig og regerede fra 1588 til 1648. Han satte sit præg på København med byggerier som Rosenborg, Børsen, Rundetårn og Nyboder og grundlagde Christianshavn. Hans krige mod Sverige og i Tyskland endte dog med store tab. Han ligger i Christian 4.s Kapel i Roskilde Domkirke.', 'Renæssancen', '1600-tallet', 'Danmark i Renæssancen', 'royals', 'https://da.wikipedia.org/wiki/Christian_4.', true)
