insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (20, 'Frederik 9.', '11. marts 1899', '14. januar 1972', '1899-03-11', '1972-01-14', 1899, 1972, 'Sorgenfri Slot', 'København', 'Konge', 'Roskilde Domkirke', 6, 'Roskilde', 55.6426, 12.0803, 'cemetery', 90, 'Folkekongen fra efterkrigstiden, der elskede musik og søfart. Begravet uden for Roskilde Domkirke.', 'Frederik 9. var konge fra 1947 til 1972 — årene hvor velfærdssamfundet blev bygget. Han var en dygtig amatørdirigent og tidligere søofficer. Med grundloven og tronfølgeloven af 1953 blev det muligt for hans datter Margrethe at arve tronen. Han blev begravet uden for Roskilde Domkirke.', 'Verdenskrigenes tid', '1900-tallet', 'Danmark i Verdenskrigenes tid', 'royals', 'https://da.wikipedia.org/wiki/Frederik_9.', true)
