insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (21, 'Ludvig Holberg', '3. december 1684', '28. januar 1754', '1684-12-03', '1754-01-28', 1684, 1754, 'Bergen', 'København', 'Forfatter og historiker', 'Sorø Klosterkirke', 7, 'Sorø', 55.432, 11.557, 'cemetery', 90, 'Den danske komedies fader. ''Jeppe på Bjerget'' og ''Erasmus Montanus'' spilles stadig på landets scener.', 'Ludvig Holberg kom fra Bergen og blev professor ved Københavns Universitet. Da det første danske teater åbnede i Lille Grønnegade i 1722, skrev han en lang række komedier, der gjorde grin med tidens typer. Han skrev også historieværker og romanen ''Niels Klims underjordiske Rejse''. Han testamenterede sin formue til Sorø Akademi og er begravet i Sorø Klosterkirke.', 'Enevælden', '1700-tallet', 'Danmark i Enevælden', 'writers', 'https://da.wikipedia.org/wiki/Ludvig_Holberg', true)
