insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (22, 'Absalon', 'ca. 1128', '21. marts 1201', null, '1201-03-21', 1128, 1201, 'Fjenneslev', 'Sorø', 'Biskop og statsmand', 'Sorø Klosterkirke', 7, 'Sorø', 55.432, 11.557, 'cemetery', 85, 'Biskoppen og krigeren, der byggede borgen på Slotsholmen og dermed grundlagde København.', 'Absalon var Valdemar den Stores fostbror og nærmeste rådgiver. Han blev biskop i Roskilde i 1158 og fik byen Havn som len af kongen. I 1167 byggede han en borg på Slotsholmen, og i 1169 ledte han erobringen af Rügen. Senere blev han ærkebiskop i Lund. Han er begravet i Sorø Klosterkirke.', 'Middelalderen', '1100-tallet', 'Danmark i Middelalderen', 'politics', 'https://da.wikipedia.org/wiki/Absalon', true)
