insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (23, 'B.S. Ingemann', '28. maj 1789', '24. februar 1862', '1789-05-28', '1862-02-24', 1789, 1862, 'Thorkildstrup på Falster', 'Sorø', 'Digter og salmedigter', 'Sorø Klosterkirke', 7, 'Sorø', 55.432, 11.557, 'cemetery', 90, 'Forfatter til ''I østen stiger solen op'', ''Dejlig er jorden'' og de historiske romaner om middelalderens konger.', 'Bernhard Severin Ingemann var lærer ved Sorø Akademi i 40 år. Hans historiske romaner som ''Valdemar Seier'' gav generationer af danskere et billede af middelalderen, og hans morgen- og aftensange samt salmer som ''Dejlig er jorden'' synges stadig.', 'Guldalderen', '1800-tallet', 'Danmark i Guldalderen', 'writers', 'https://da.wikipedia.org/wiki/B.S._Ingemann', true)
