insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (24, 'Karen Blixen', '17. april 1885', '7. september 1962', '1885-04-17', '1962-09-07', 1885, 1962, 'Rungsted', 'Rungsted', 'Forfatter', 'Rungstedlund', 8, 'Rungsted', 55.883, 12.5445, 'cemetery', 90, 'Forfatteren bag ''Den afrikanske farm'' og ''Babettes gæstebud''. Hun ligger begravet under en bøg ved Rungstedlund.', 'Karen Blixen drev en kaffefarm i Kenya fra 1914 til 1931. Tilbage i Rungsted debuterede hun under navnet Isak Dinesen med ''Seven Gothic Tales'' i 1934, og ''Den afrikanske farm'' fra 1937 gjorde hende verdensberømt. Hun er begravet på Ewalds Høj i parken ved Rungstedlund.', 'Verdenskrigenes tid', '1900-tallet', 'Danmark i Verdenskrigenes tid', 'writers', 'https://da.wikipedia.org/wiki/Karen_Blixen', true)
