insert into persons (id, name, born, died, birth_date, death_date, birth_year, death_year, birth_place, death_place, profession, cemetery, cemetery_id, city, lat, lng, location_precision, confidence, short_bio, full_bio, era, era_years, time_window_title, category, wikipedia_url, curated) values (25, 'Valdemar den Store', '14. januar 1131', '12. maj 1182', '1131-01-14', '1182-05-12', 1131, 1182, 'Slesvig', 'Vordingborg', 'Konge', 'Sankt Bendts Kirke', 9, 'Ringsted', 55.4446, 11.7902, 'cemetery', 85, 'Kongen der samlede Danmark efter årtiers borgerkrig og indledte Valdemarstiden sammen med Absalon.', 'Valdemar 1. blev født kort efter, at hans far Knud Lavard var blevet myrdet. Efter borgerkrigen og sejren på Grathe Hede i 1157 blev han enekonge. Sammen med Absalon førte han korstog mod venderne og erobrede Rügen i 1169. Han er begravet i Sankt Bendts Kirke i Ringsted.', 'Middelalderen', '1100-tallet', 'Danmark i Middelalderen', 'royals', 'https://da.wikipedia.org/wiki/Valdemar_den_Store', true)
